// lib/inngest.ts — shared client
import { Inngest } from 'inngest';

export const inngest = new Inngest({
  id: 'my-app',
  eventKey: process.env.INNGEST_EVENT_KEY,
});

// inngest/send-welcome-email.ts — function definition
import { inngest } from '../lib/inngest';

export const sendWelcomeEmail = inngest.createFunction(
  { id: 'send-welcome-email', retries: 3 },
  { event: 'user/signup.created' },
  async ({ event, step }) => {
    const { userId, email } = event.data;

    await step.run('send-email', async () => {
      // Any thrown error here triggers a retry of this step only
      await fetch('https://api.email.com/send', {
        method: 'POST',
        body: JSON.stringify({ to: email, subject: 'Welcome!' }),
      });
    });

    return { sent: true, userId };
  }
);

// app/api/route.ts — trigger an event from your API
import { inngest } from '../../lib/inngest';

export async function POST(req: Request) {
  const body = await req.json();

  await inngest.send({
    name: 'user/signup.created',
    data: { userId: body.userId, email: body.email },
  });

  return Response.json({ ok: true });
}

import { inngest } from '../lib/inngest';
import { db } from '../lib/db';
import { resend } from '../lib/resend';

export const onboardUser = inngest.createFunction(
  { id: 'onboard-user', retries: 5 },
  { event: 'user/signup.created' },
  async ({ event, step }) => {
    const { userId } = event.data;

    // Step 1: Fetch user data — retried independently if it fails
    const user = await step.run('fetch-user', async () => {
      return db.users.findUnique({ where: { id: userId } });
    });

    // Step 2: Send welcome email — only runs after step 1 succeeds
    await step.run('send-welcome-email', async () => {
      await resend.emails.send({
        from: 'hello@acme.com',
        to: user.email,
        subject: 'Welcome to Acme!',
        html: `<h1>Hi ${user.name}!</h1>`,
      });
    });

    // Step 3: Update onboarding status in DB
    await step.run('mark-onboarded', async () => {
      await db.users.update({
        where: { id: userId },
        data: { onboardedAt: new Date() },
      });
    });

    return { userId, onboarded: true };
  }
);
